'use client';

import React, { useState } from 'react';
import { AnimatedImageGrid } from '@/components/core/animated-image-grid';
import { Plus, Minus } from 'lucide-react';
import { Button } from '@/components/ui/button';

// Helper to generate a random image from pravatar
const getRandomImage = (id: string | number) => ({
  id,
  src: `https://i.pravatar.cc/150?img=${Math.floor(Math.random() * 40) + 1}`,
});

const INITIAL_ITEMS = Array.from({ length: 18 }, (_, i) => getRandomImage(i));

export function AnimatedImageGridBasic() {
  const [items, setItems] = useState(INITIAL_ITEMS);

  const handleAdd = () => {
    const newItem = getRandomImage(Date.now());

    // Randomly insert at beginning or at a random position to show off the reflow animation
    const position = Math.floor(Math.random() * (items.length + 1));
    const newItems = [...items];
    newItems.splice(position, 0, newItem);

    setItems(newItems);
  };

  const handleRemove = () => {
    if (items.length === 0) return;

    // Randomly remove an item to show off the reflow animation
    const position = Math.floor(Math.random() * items.length);
    const newItems = [...items];
    newItems.splice(position, 1);

    setItems(newItems);
  };

  return (
    <div className='flex min-h-[500px] w-full flex-col items-center rounded-xl bg-[#d3d9b3] p-8'>
      <div className='mb-8 flex gap-4'>
        <Button
          onClick={handleAdd}
          className='h-12 w-12 rounded-xl bg-[#8A9B0F] text-2xl text-white shadow-md hover:bg-[#6c790b]'
        >
          <Plus className='h-6 w-6' />
        </Button>
        <Button
          onClick={handleRemove}
          className='h-12 w-12 rounded-xl bg-[#BD1550] text-2xl text-white shadow-md hover:bg-[#9a1040]'
        >
          <Minus className='h-6 w-6' />
        </Button>
      </div>

      <div className='w-full max-w-4xl rounded-xl border-2 border-red-500 bg-[#d3d9b3]'>
        <AnimatedImageGrid items={items} gap='10px' size='130px' />
      </div>
    </div>
  );
}

@reference "../../app/globals.css";

.animated-image-grid {
  --animated-grid-gap: var(--grid-gap, 10px);
  --animated-grid-size: var(--grid-size, 130px);

  display: grid;
  grid-template-columns: repeat(auto-fill, var(--animated-grid-size));
  grid-auto-rows: var(--animated-grid-size);
  gap: var(--animated-grid-gap);
  justify-content: center;
  container-type: inline-size;
}

.animated-image-grid-item {
  grid-area: 1 / 1;
  width: var(--animated-grid-size);
  aspect-ratio: 1;
  box-sizing: border-box;

  /* Dynamically calculate the number of columns using the container's width */
  --n: round(
    down,
    (100cqw + var(--animated-grid-gap)) /
      (var(--animated-grid-size) + var(--animated-grid-gap))
  );

  /* Calculate row and column indices based on the injected --index custom property */
  --i: round(down, var(--index) / var(--n));
  --j: mod(var(--index), var(--n));

  /* Translate the item into its calculated position */
  translate: calc(var(--j) * (100% + var(--animated-grid-gap)))
    calc(var(--i) * (100% + var(--animated-grid-gap)));

  transition:
    0.4s,
    scale 0.3s 0.4s,
    opacity 0.3s 0.3s,
    rotate 0.3s 0.3s;

  @starting-style {
    scale: 0;
    opacity: 0;
    rotate: -1turn;
  }
}

/* A hack to fix the grid container size, since all items are stacked at 1/1 */
.animated-image-grid-filler {
  translate: 0;
  visibility: hidden;
  grid-row: calc(var(--i) + min(var(--j), 1));
}

import * as React from 'react';
import { cn } from '@/lib/utils';
import './animated-image-grid.css';

export interface AnimatedImageGridItem {
  id: string | number;
  src: string;
  alt?: string;
}

export interface AnimatedImageGridProps extends React.HTMLAttributes<HTMLDivElement> {
  items: AnimatedImageGridItem[];
  gap?: string;
  size?: string;
}

export const AnimatedImageGrid = React.forwardRef<
  HTMLDivElement,
  AnimatedImageGridProps
>(({ className, items, gap, size, style, ...props }, ref) => {
  // Inject the customizable gap and size variables if provided
  const customStyle = {
    ...(gap ? { '--grid-gap': gap } : {}),
    ...(size ? { '--grid-size': size } : {}),
    ...style,
  } as React.CSSProperties;

  return (
    <div
      ref={ref}
      className={cn('animated-image-grid h-full w-full p-4', className)}
      style={customStyle}
      {...props}
    >
      {items.map((item, index) => (
        <div
          key={item.id}
          className='animated-image-grid-item border-primary/20 overflow-hidden rounded-lg border-2 shadow-sm'
          style={{ '--index': index } as React.CSSProperties}
        >
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={item.src}
            alt={item.alt || `Grid image ${index}`}
            className='h-full w-full object-cover'
          />
        </div>
      ))}
      {/* Hidden filler element required to stretch the container height hack */}
      <div
        className='animated-image-grid-item animated-image-grid-filler'
        style={{ '--index': items.length } as React.CSSProperties}
      />
    </div>
  );
});
AnimatedImageGrid.displayName = 'AnimatedImageGrid';
